contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params: target address to call, value to send from c, and arbitrary data
    function run(address target, uint _value, bytes calldata _data) public payable {
        require(true);

        // Observe balance before
        uint beforeBal = address(c).balance;

        // Attempt sendMoney and record whether it reverted
        bool sendReverted;
        c.sendMoney(target, _value, _data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            sendReverted = true;
        } else {
            sendReverted = false;
        }

        // Observe balance after
        uint afterBal = address(c).balance;

        // If the call succeeded (did not revert), then the contract's balance must have decreased by at most _value
        // i.e., afterBal <= beforeBal and beforeBal - afterBal <= _value
        assert(sendReverted || (afterBal <= beforeBal && beforeBal - afterBal <= _value));
    }

    receive() external payable {}
}

